insert into public.procurement_doc(page_id,category,title,published_on,source_url,file_urls,text_quality) values (71,'تعاميم','تعميم رقم 16/2024 صادر عن غرفة التجارة والصناعة والزراعة يتعلق بكيفية التحقق من صحة المستندات الصادرة والموقع عليها من قبل الغرفة','2024-08-13','https://www.ppa.gov.lb/ar/pages/details/71','{"https://admin.ppa.gov.lb/storage/listing-pages/files/asvO4js7FT9ZDIOpOjwfGYAc354C8fiGJVQK-1760218575.pdf","https://admin.ppa.gov.lb/storage/listing-pages/files/asvO4js7FT9ZDIOpOjwfGYAc354C8fiGJVQK-1760218575.pdf"}','ocr') on conflict (page_id) do update set category=excluded.category,title=excluded.title,published_on=excluded.published_on,file_urls=excluded.file_urls,text_quality=excluded.text_quality;
insert into public.procurement_doc_chunk(doc_id,ord,label,body) select (select id from public.procurement_doc where page_id=71),(e->>'o')::int,e->>'l',e->>'b' from jsonb_array_elements($j$[{"o": 0, "l": null, "b": "غرفة التجارة والصناعة 4ي\nةربن وم 0\nقب بيروت وجبل لبنان 0د دجاع ا\" وناماا 200 نم88 أن بيروت فى ١ آب 7074\nجانب هيئة الشراء العام\nتعميم صادر رقم ٠١74/١7 عن غرفة التجارة والصناعة والزراعة في بيروت وجبل لبنان\nحرصاً على حسن التعاون والتنسيق بين غرفة التجارة والصناعة والزراعة في بيروت وجبل لبنان وكافة المؤسسات\nوالادارات الرسمية في لبنان والخارج» خاصة فيما يتعلق بصحة الفواتير والتواقيع والشهادات الصادرة والمصادق\nعليها من قبل الغرفة»\nوحيث أن الغرفة باتت تعتمد في معاملاتها أحدث التقنيات الفنية والإلكترونية لضمان الشفافية والسربة وعدم إمكانية\nتزوير المستندات الصادرة عنهاء نفيدكم بالميزات التالية:\n« على شهادات المنشأ الصادرة والمصادق عليها ضمن إطار جامعة الدول العربية (نموذج :)١\n- ملصق هولوغرام ثلاثي الأبعاد غير قابل للتزوير في أعلى يسار الشهادة؛\n- رمز 2008© 05 ورمزه المشفر غير القابل للتزويرء في وسط أسفل الشهادة والذي يمكن مسحه بواسطة\nجهازن هاتف محمول للاطلاع على المعلومات الاساسية ضمن كل شهادة\nإضافة الى إمكانية تحميل صورة عن الشهادة؛\n- ختم الغرفة مستطيل الشكل في وسط أسفل الشهادة» وهو ختم مرمز يحتوي على دلالات مشفرة غير قابلة\nللتزوير.\nه على شهادات المنشأ التي تحمل اسم وشعار الغرفة (نموذج ؟):\n- شعار غرقة التجارة الدولية في باريس 5215 100 في أعلى الشهادة؛ .\n- ملصق هولوغرام ثلاثي الأبعاد غير قابل للتزوير في أعلى الشهادة؛\n- رمز 0006© © ورمزه المشفر غير القابل للتزويرء في يمين أسفل الشهادة والذي يمكن مسحه بواسطة\nجهازن هاتف محمول للاطلاع على المعلومات الاساسية ضمن كل شهادة\nإضافة الى إمكانية تحميل صورة عن الشهادة؛\n- ختم الغرفة مستطيل الشكل في وسط أسفل الشهادة؛ وهو ختم مرمز يحتوي على دلالات مشفرة غير قابلة\nللتزوير.\nه على شهادات الانتساب والشهادات الخاصة التي تحمل اسم وشعار الغرفة (نموذج \"):"}, {"o": 1, "l": null, "b": "- ملصق هولوغرام ثلاثي الأبعاد غير قابل للتزوير في أعلى الشهادة؛\nمبنى غرفة التجارة والصناعة والزراعة في بيروت وجبل لبنان 1 آلآ لك طارع:ه.طاعء © مم2 ممما\nشارع جوستينيان1, الصنائع. ص.ب. 1801 11 بيروت, لبنان 7 طاءع نه طاعع .نايا\nعي 0 نه 8 8 ه ©\n- رمز 0086© 018 ورمزه المشفر غير القابل للتزويرء في أعلى الشهادة والذي يمكن مسحه بواسطة جهاز\nهاتف محمول للاطلاع على المعلومات الاساسية ضمن كل شهادة؛\n- ختم الغرفة مستطيل الشكل في وسط أسفل الشهادة؛ وهو ختم مرمز يحتوي على دلالات مشفرة غير قابلة\nللتزوير.\nه للمصادقة على الفواتير المعدة للتصدير واصدار شهادة منشأ (نموذج 4):\n- اعتماد لاصق |1306 غير قابل للنزع والتزوير يحمل عبارة 'تصادق غرفة التجارة والصناعة والزراعة في\nبيروت وجبل لبنان على أن منشأ البضاعة المذكورة في هذه الفاتورة ...\" باللغة العربية أو الاجنبية\n- رمز 0808© © ورمزه المشفر غير القابل للتزوير» والذي يمكن مسحه بواسطة جهاز هاتف محمول\nللاطلاع على المعلومات الاساسية ضمن كل شهادة؛\n- ختم الغرفة مستطيل الشكل في الاسفل» وهو ختم مرمز يحتوي على دلالات مشفرة غير قابلة للتزودر.\nه للمصادقة على صحة توقيع المفوضين بالتوقيع (نموذج 5):\n- اعتماد لاصق |3506 :غير قابل للنزع أو التزوير يحمل عبارة 'تصادق غرفة التجارة والصناعة والزراعة\nفي بيروت وجبل لبنان على صحة توقيع (الاسم والمؤسسة)' باللغة العربية أو الاجنبية؛\n- رمز ©00© © ورمزه المشفر غير القابل للتزويرء والذي يمكن مسحه بواسطة جهاز هاتف محمول\nللاطلاع على المعلومات الخاصة بكل مصادقة؛\n- ختم الغرفة مستطيل الشكل في الاسفل» وهو ختم مرمز يحتوي على دلالات مشفرة غير قابلة للتزوبر.\n٠ للاطلاع على مضمون شهادات المنشأ الصادرة عن الغرفة وللتحقق من صحتها (نموذج 5):\n- عبر الرابط الإلكتروني 1105:///©1/.6610.019.15 بعد ادخال كل من رقم الشهادة وسنة الاصدار"}, {"o": 2, "l": null, "b": "والرمز المشفر الظاهر تحت رمز 0006 015؛\n- أو مسح رمز 0008 0158© بواسطة جهاز هاتف محمول.\nنأمل المساهمة في تعميم المعلومات الواردة أعلاه على كافة الدوائر والمراجع المعنية ذات الصلة؛ علماً أن جهازنا\nالإداري والفني في الخدمة للإجابة على أية إستفسارات 6615.09.16 01010241006ا\n4 معهعامعه الهه.\nالمدير العا\n77 /// ||[ |[ [[ 1/111\n:بيع صنوام .سح كرس سس و 7 2 غرضة التجارة والطناعة والزراعة ”راح\nْ ا ات ل ات ال ا\n2\n5 0-7 2-9 : دما\nلهرت لحان 55 #قق د\nغرفة التجارة والصناعة والزراعة 0 و م\